#include <iostream>
#include <string>
class MyClass {
public:
  std::string data;
  MyClass(const std::string& d) : data(d) { std::cout << "Constructor called for: " << data << std::endl; }
  MyClass(MyClass&& other) noexcept : data(std::move(other.data)) { std::cout << "Move constructor called for: " << data << std::endl; }
  MyClass(const MyClass& other) : data(other.data) { std::cout << "Copy constructor called for: " << data << std::endl; }
  ~MyClass() { std::cout << "Destructor called for: " << data << std::endl; }
};
MyClass createMyClass(const std::string& data) {
  MyClass obj(data);
  return obj;
}
int main() {
  auto myObj = createMyClass("Test");
  return 0;
}
